import { Router } from "express";
import { requireAuth } from "./auth.js";
import { storage } from "./storage.js";
import { generateFinancialLiteracyCourse, generateAchievementBadges } from "./courseContentGenerator.js";
import { z } from "zod";

const router = Router();

// Get course content (generated by GPT-4o)
router.get("/api/courses/content", async (req, res) => {
  try {
    const modules = await generateFinancialLiteracyCourse();
    res.json({ modules });
  } catch (error) {
    console.error("Error generating course content:", error);
    res.status(500).json({ error: "Failed to generate course content" });
  }
});

// Get achievement badges (generated by GPT-4o)
router.get("/api/courses/badges", async (req, res) => {
  try {
    const badges = await generateAchievementBadges();
    res.json({ badges });
  } catch (error) {
    console.error("Error generating badges:", error);
    res.status(500).json({ error: "Failed to generate badges" });
  }
});

// Get user's course progress
router.get("/api/courses/progress", requireAuth, async (req, res) => {
  try {
    const userId = req.auth.userId;
    const progress = await storage.getUserCourseProgress(userId);
    const stats = await storage.getUserLearningStats(userId);
    const achievements = await storage.getUserAchievements(userId);
    
    res.json({ 
      progress: progress || [],
      stats: stats || {
        totalXp: 0,
        currentStreak: 0,
        longestStreak: 0,
        totalLessonsCompleted: 0,
        totalTimeSpent: 0,
        averageScore: 0
      },
      achievements: achievements || []
    });
  } catch (error) {
    console.error("Error fetching user progress:", error);
    res.status(500).json({ error: "Failed to fetch course progress" });
  }
});

// Submit exercise completion
const submitExerciseSchema = z.object({
  moduleId: z.string(),
  levelId: z.string(),
  score: z.number().min(0).max(100),
  timeSpent: z.number().min(0), // seconds
  isCompleted: z.boolean()
});

router.post("/api/courses/submit-exercise", requireAuth, async (req, res) => {
  try {
    const userId = req.auth.userId;
    const data = submitExerciseSchema.parse(req.body);
    
    // Update course progress
    await storage.updateCourseProgress(userId, {
      moduleId: data.moduleId,
      levelId: data.levelId,
      score: data.score,
      timeSpent: data.timeSpent,
      isCompleted: data.isCompleted,
      completedAt: data.isCompleted ? new Date() : null
    });

    // Update learning stats
    await storage.updateLearningStats(userId, {
      xpGained: data.score,
      timeSpent: data.timeSpent,
      lessonCompleted: data.isCompleted
    });

    // Check for new achievements
    const newBadges = await checkForNewAchievements(userId);
    
    res.json({ 
      success: true, 
      xpGained: data.score,
      newBadges: newBadges || []
    });
  } catch (error) {
    console.error("Error submitting exercise:", error);
    res.status(500).json({ error: "Failed to submit exercise" });
  }
});

// Achievement checking logic
async function checkForNewAchievements(userId: string) {
  try {
    const stats = await storage.getUserLearningStats(userId);
    const existingAchievements = await storage.getUserAchievements(userId);
    const earnedBadgeIds = new Set(existingAchievements.map(a => a.badgeId));
    
    const newBadges = [];
    
    // Check for first lesson completion
    if (stats.totalLessonsCompleted >= 1 && !earnedBadgeIds.has('first-lesson')) {
      await storage.awardAchievement(userId, 'first-lesson');
      newBadges.push('first-lesson');
    }
    
    // Check for streak achievements
    if (stats.currentStreak >= 7 && !earnedBadgeIds.has('week-streak')) {
      await storage.awardAchievement(userId, 'week-streak');
      newBadges.push('week-streak');
    }
    
    if (stats.currentStreak >= 30 && !earnedBadgeIds.has('month-streak')) {
      await storage.awardAchievement(userId, 'month-streak');
      newBadges.push('month-streak');
    }
    
    // Check for completion achievements
    if (stats.totalLessonsCompleted >= 9 && !earnedBadgeIds.has('course-complete')) {
      await storage.awardAchievement(userId, 'course-complete');
      newBadges.push('course-complete');
    }
    
    return newBadges;
  } catch (error) {
    console.error("Error checking achievements:", error);
    return [];
  }
}

export default router;